'use strict';
function campaignCosts(v){
 const keys=['months','sites','aSetup','aMonthly','aVisits','aVisitCost','bSetup','bMonthly','bVisits','bVisitCost'];
 if(keys.some(k=>!Number.isFinite(v[k])||v[k]<0)||!Number.isInteger(v.months)||!Number.isInteger(v.sites)||!Number.isInteger(v.aVisits)||!Number.isInteger(v.bVisits)||v.months<1||v.months>120||v.sites<1||v.sites>1000||v.aVisits>1000||v.bVisits>1000||keys.filter(k=>!['months','sites','aVisits','bVisits'].includes(k)).some(k=>v[k]>1e8))throw Error('Use valid campaign inputs.');
 const a=v.sites*(v.aSetup+v.months*v.aMonthly+v.aVisits*v.aVisitCost),b=v.sites*(v.bSetup+v.months*v.bMonthly+v.bVisits*v.bVisitCost),saving=a-b,investment=v.sites*(v.bSetup-v.aSetup),monthlySaving=v.sites*(v.aMonthly-v.bMonthly);
 return {a,b,saving,percent:a>0?saving/a*100:null,investment,roi:investment>0?saving/investment*100:null,payback:investment>0&&monthlySaving>0?investment/monthlySaving:null};
}
if(typeof module!=='undefined')module.exports=campaignCosts;
if(typeof document!=='undefined')(()=>{
 const form=document.querySelector('[data-cro-calculator]');if(!form)return;
 const arabic=document.documentElement.lang==='ar',tr=(en,ar)=>arabic?ar:en;
 const results=document.getElementById('calculator-results'),status=document.getElementById('calculator-status'),feedback=document.getElementById('calculator-feedback');let summary='';
 const show=(id,text)=>document.getElementById(id).textContent=text;
 const money=(value,currency)=>new Intl.NumberFormat('en-SA',{style:'currency',currency,maximumFractionDigits:0}).format(value);
 function edit(){form.hidden=false;results.hidden=true;status.textContent=tr('Step 1 of 2 · Define your scenarios','الخطوة 1 من 2 · حدّد السيناريوهات');form.querySelector('input').focus();}
 document.querySelector('[data-edit-scenario]').addEventListener('click',edit);
 document.querySelector('[data-cro-example]').addEventListener('click',()=>{const vals={months:24,sites:1,aSetup:60000,aMonthly:3500,aVisits:8,aVisitCost:2500,bSetup:85000,bMonthly:1800,bVisits:4,bVisitCost:2500};Object.entries(vals).forEach(([k,v])=>form.elements[k].value=v);status.textContent=tr('Illustrative example loaded. Review each assumption, then calculate.','تم تحميل مثال توضيحي. راجع كل افتراض ثم احسب.');});
 form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form)),currency=data.currency;Object.keys(data).filter(k=>k!=='currency').forEach(k=>data[k]=Number(data[k]));let r;try{r=campaignCosts(data)}catch(err){status.textContent=tr(err.message,'أدخل قيمًا صحيحة للحملة.');return;}
 show('result-basis',data.sites+tr(' site(s) · ',' موقع · ')+data.months+tr(' months · ',' شهر · ')+currency+tr(' · User-entered scenario',' · سيناريو أدخله المستخدم'));show('cost-a',money(r.a,currency));show('cost-b',money(r.b,currency));show('cost-saving',money(r.saving,currency));show('saving-percent',r.percent===null?tr('Baseline is zero; percentage is undefined.','خط الأساس صفر؛ لا يمكن حساب النسبة.'):r.percent.toFixed(1)+tr('% of Option A cost','% من تكلفة الخيار A')+(r.saving<0?tr(' · Option B costs more.',' · الخيار B أعلى تكلفة.'):''));show('additional-investment',r.investment>0?money(r.investment,currency):tr('No additional setup investment in Option B.','لا يوجد استثمار تجهيز إضافي في الخيار B.'));show('simple-roi',r.roi===null?tr('Not applicable without additional setup investment.','غير منطبق دون استثمار تجهيز إضافي.'):r.roi.toFixed(1)+tr('% across the campaign','% على مدى الحملة'));show('simple-payback',r.payback===null?tr('Not applicable: requires additional setup investment and positive monthly operating savings.','غير منطبق: يتطلب استثمار تجهيز إضافيًا ووفورات تشغيل شهرية موجبة.'):r.payback.toFixed(1)+tr(' months',' شهر')+(r.payback>data.months?tr(' · Beyond the selected campaign duration.',' · بعد مدة الحملة المختارة.'):'')+tr(' · Based on monthly operating savings only.',' · بناءً على وفورات التشغيل الشهرية فقط.'));
 summary=tr('EnviroMET campaign cost scenario\nCurrency: ','سيناريو تكلفة حملة EnviroMET\nالعملة: ')+currency+tr('\nSites: ','\nالمواقع: ')+data.sites+tr('\nDuration: ','\nالمدة: ')+data.months+tr(' months\n',' شهر\n')+['a','b'].map(k=>tr('Option ','الخيار ')+k.toUpperCase()+tr(' per site: setup ',' لكل موقع: التجهيز ')+data[k+'Setup']+tr(', monthly ','، شهريًا ')+data[k+'Monthly']+tr(', visits ','، الزيارات ')+data[k+'Visits']+tr(', visit cost ','، تكلفة الزيارة ')+data[k+'VisitCost']).join('\n')+tr('\nOption A total: ','\nإجمالي الخيار A: ')+money(r.a,currency)+tr('\nOption B total: ','\nإجمالي الخيار B: ')+money(r.b,currency)+tr('\nNet saving: ','\nصافي الوفر: ')+money(r.saving,currency)+tr('\nSimple ROI: ','\nالعائد البسيط على الاستثمار: ')+document.getElementById('simple-roi').textContent+tr('\nPayback: ','\nفترة الاسترداد: ')+document.getElementById('simple-payback').textContent+tr('\nUser assumptions only; excludes tax, financing, discounting, inflation and unplanned outages. Equivalent scope must be confirmed.','\nافتراضات المستخدم فقط؛ لا تشمل الضرائب أو التمويل أو خصم التدفقات النقدية أو التضخم أو الأعطال غير المخطط لها. يجب تأكيد تكافؤ النطاق.');
 form.hidden=true;results.hidden=false;results.focus();feedback.textContent=tr('Review or download the comparison, then discuss your requirements.','راجع المقارنة أو حمّلها، ثم ناقش متطلباتك.');
 });
 document.querySelector('[data-share-scenario]').addEventListener('click',()=>{try{sessionStorage.setItem('enviromet-campaign-scenario',summary)}catch{ /* Download remains available if storage is disabled. */ }});
 document.querySelector('[data-download-scenario]').addEventListener('click',()=>{const blob=new Blob([summary],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='EnviroMET_Campaign_Comparison.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);feedback.textContent=tr('Comparison downloaded with your assumptions and calculation basis.','تم تحميل المقارنة مع افتراضاتك وأساس الحساب.');});
})();
